// Gate + defaults. This webhook triggers PAID renders — when the instance is
// exposed to the internet (it must be, for GitHub to reach it), set
// RENDER_WEBHOOK_TOKEN and callers must present it (x-render-token header or
// body.token).
const j = $('Render request').first().json;
const body = j.body || {};
const expected = $env.RENDER_WEBHOOK_TOKEN || '';
if (expected) {
  const got = (j.headers && j.headers['x-render-token']) || body.token || '';
  if (got !== expected) throw new Error('invalid or missing render token');
}
const movieId = body.movieId;
if (!movieId) throw new Error('body.movieId is required (the ?movieId= param on the IG grid)');
return [{ json: { movieId, force: body.force !== false, chatId: body.chatId || '', base: $env.YAKYAK_API_BASE || 'https://api.yakyak.ai' } }];

const ex = {};
for (const e of ($json.executions || [])) ex[e.type] = e.status;
if (ex.movieConcat === 'failed' || ex.movieSoundtrack === 'failed') throw new Error('render failed');
const done = ex.movieConcat === 'completed' && (ex.movieSoundtrack === undefined || ex.movieSoundtrack === 'completed');
return [{ json: { done } }];

// sendVideo fetches the mp4 by URL server-side, so the video arrives PLAYABLE
// in the chat (≤ ~20 MB). On any failure fall back to a link message — never
// lose a finished render.
const movie = ($json.movie || $json);
const url = movie.finalMovieUrl || movie.soundtrackedMovieUrl || movie.concatMovieUrl;
if (!url) throw new Error('render completed but get-movie returned no movie URL');
const title = movie.title || 'YakYak movie';
const chatId = $('Validate').first().json.chatId || $env.TELEGRAM_CHAT_ID;
if (!chatId) throw new Error('no chat id — set TELEGRAM_CHAT_ID on the instance or pass chatId in the body');
const bot = $env.TELEGRAM_BOT_TOKEN;
if (!bot) throw new Error('TELEGRAM_BOT_TOKEN env var is not set');
const caption = `\u{1F3AC} ${title}\n${url}`;
const tg = (method, body) => this.helpers.httpRequest({
  method: 'POST', url: `https://api.telegram.org/bot${bot}/${method}`,
  body, json: true,
});
let delivered = 'video';
try {
  await tg('sendVideo', { chat_id: chatId, video: url, caption });
} catch (e) {
  await tg('sendMessage', { chat_id: chatId, text: caption });
  delivered = 'link';
}
return [{ json: { url, title, movieId: $('Validate').first().json.movieId, delivered } }];
